        let mut entry_v2 = encode_verifier_registry_entry_v2(&entry_v2()).unwrap();
        entry_v2[4] = 2;
        entry_v2[312] = 0;
        entry_v2[313] = 0;
        assert_eq!(
            decode_verifier_registry_entry_v2(&entry_v2),
            Err(PoolV1VerifierRegistryFormatError::WrongVersion)
        );
    }
}

